<section class="panel"><div class="panel-head"><div><h2>Audit log</h2><p>مقادیر حساس پیش از ثبت Redact شده‌اند.</p></div></div><div class="table-wrap"><table><thead><tr><th>زمان</th><th>Actor</th><th>Action</th><th>Entity</th><th>IP</th><th>تغییرات</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6"><div class="empty">رویدادی ثبت نشده است.</div></td></tr><?php else:foreach($rows as$row):?><tr><td><?= \CardPay\Core\View::e(\CardPay\Core\View::localDate($row['created_at'],(string)($settings['timezone']??'Asia/Tehran'))) ?></td><td><?= \CardPay\Core\View::e($row['actor_type']) ?> <?= \CardPay\Core\View::e($row['actor_id']) ?></td><td><strong><?= \CardPay\Core\View::e($row['action']) ?></strong></td><td><?= \CardPay\Core\View::e(($row['entity_type']??'').' #'.($row['entity_id']??'')) ?></td><td><?= \CardPay\Core\View::e($row['ip']) ?></td><td><details><summary>نمایش</summary><pre><?= \CardPay\Core\View::e($row['new_values']??$row['old_values']??'{}') ?></pre></details></td></tr><?php endforeach;endif;?></tbody></table></div></section>
